def get_state_values(grid):
    rows = len(grid)
    cols = len(grid[0])

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == "X":
                continue

            if (i, j) == (rows - 1, cols - 1):  
                # Goal state
                grid[i][j] = 'G'

            elif (i == 0 or i == rows-1 or j == 0 or j == cols-1):
                grid[i][j] += 2

            else:
                grid[i][j] += 3

    return [[int(state) for state in row] for row in grid]


