}

# Define valid movements (cardinal directions)
movements = [(0, 1), (0, -1), (1, 0), (-1, 0)]

# Initialize a set to store visited states
visited_states = set()

# Initialize a dictionary to store the grid indices for each state
state_to_index = {}
for i in range(len(grid_world["grid"])):
    for j in range(len(grid_world["grid"][i])):
        # Map each state to its index in the grid (x, y)
        state_to_index[(i, j)] = (i, j)

# Define a function to get adjacent states
def get_adjacent_states(state):
    x, y = state_to_index[state]
    adjacent_states = []

    for movement in movements:
        new_x, new_y = x + movement[0], y + movement[1]

        # Check if the new position is within the grid boundaries
        if 0 <= new_x < len(grid_world["grid"]) and 0 <= new_y < len(grid_world["grid"][new_x]):
            adjacent_states.append((new_x, new_y))

    return adjacent_states

# Define a function to get all reachable states from a given state
def get_reachable_states(state):
    visited = set()
    stack = [state]

    while stack:
        current_state = stack.pop()

        if current_state not in visited and current_state not in visited_states:
            visited.add(current_state)

            # Get adjacent states
            for adjacent_state in get_adjacent_states(current_state):
                # Check if the adjacent state is valid (i.e., it's within the grid boundaries)
                if adjacent_state not in visited_states:
                    stack.append(adjacent_state)

    return list(visited)

