import networkx as nx

def group_states(grid):
    # Create a directed graph with nodes representing states and edges between adjacent states
    G = nx.DiGraph()

    # Add nodes for each cell in the grid
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            if grid[i][j] != 'X':
                G.add_node((i, j))

    # Add edges between adjacent cells
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            if grid[i][j] != 'X' and (i > 0 or j > 0):
                if i > 0:
                    G.add_edge((i, j), (i-1, j))
                if j > 0:
                    G.add_edge((i, j), (i, j-1))

    # Find connected components
    return [list(c) for c in nx.connected_components(G)]


